import{_ as t,o as s,c as i,a3 as a,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/suchen-gruppenprozesse/gruppenprozesse-klassenunterricht-bearbeiten.png",k=JSON.parse('{"title":"Nicht kursgebundenen Klassenunterricht bearbeiten","description":"","frontmatter":{"title":"Nicht kursgebundenen Klassenunterricht bearbeiten","source_pageid":298,"source_revision":5343},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/klassenunterrichte-bearbeiten-gruppenprozesse-faecher.md","filePath":"schild3/suchen-gruppenprozesse/klassenunterrichte-bearbeiten-gruppenprozesse-faecher.md"}'),p={name:"schild3/suchen-gruppenprozesse/klassenunterrichte-bearbeiten-gruppenprozesse-faecher.md"};function c(l,r,h,d,o,b){return s(),i("div",null,[...r[0]||(r[0]=[a('<h1 id="nicht-kursgebundenen-klassenunterricht-bearbeiten" tabindex="-1">Nicht kursgebundenen Klassenunterricht bearbeiten <a class="header-anchor" href="#nicht-kursgebundenen-klassenunterricht-bearbeiten" aria-label="Permalink to &quot;Nicht kursgebundenen Klassenunterricht bearbeiten&quot;">​</a></h1><p>Bearbeiten Sie den Klassenunterricht der ausgewählten Schülergruppe. Der Gruppenprozess zeigt die nicht kursgebundenen Fächer mit der Kursart PUK.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-klassenunterricht-bearbeiten.png"><img src="'+u+'" alt="Mit dem Gruppenprozess Klassenunterrichte bearbeiten können in den Leistungsdaten existierende Fächer verändert werden." loading="lazy"></a></p><p><em>Mit dem Gruppenprozess <strong>Klassenunterrichte bearbeiten</strong> können in den Leistungsdaten existierende Fächer verändert werden.</em></p><p>Mit dem Aufruf des Gruppenprozesses <strong>Klassenunterrichte bearbeiten</strong> erscheint das Fenster &quot;Nicht-kursgebundene Fächer bearbeiten&quot;.</p><p>Hier wird also der Unterricht angezeigt, den die Schülerinnen und Schüler im Klassenverband haben, daher haben die hier gezeigten Fächer die Kursart <em>PUK</em>.</p><p>Dieser Gruppenprozess dient der Bearbeitung der <em>nicht-kursgebundenen Fächer</em> der ausgewählten Schülerinnen und Schüler.</p><p>Eine detaillierte Erläuterung ist oben in dem Fenster nachzulesen, das hier als Screenshot abgebildet ist.</p>',8),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Neueingaben von Fächern erfolgt über den gesonderten "),e("em",null,"Gruppenprozesse ➜ Fächer'"),n(" ➜ "),e("strong",null,"Einzelne Fächer bei Schülern hinzufügen"),n(".")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Klassenunterrichte_bearbeiten_(Gruppenprozesse_F%C3%A4cher)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5343.")],-1)])])}const m=t(p,[["render",c]]);export{k as __pageData,m as default};
